CREATE DATABASE IF NOT EXISTS `jojobot`; USE `jojobot`; 
SET FOREIGN_KEY_CHECKS=0;
SET UNIQUE_CHECKS=0;
DROP TABLE IF EXISTS `app_write`;
CREATE TABLE `app_write` (
  `app_id` varchar(32) NOT NULL,
  `event_key` varchar(128) NOT NULL,
  `digest` varchar(64) NOT NULL,
  `landed` text NOT NULL,
  `written_at` varchar(48) NOT NULL,
  PRIMARY KEY (`app_id`,`event_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
DROP TABLE IF EXISTS `charter_change`;
CREATE TABLE `charter_change` (
  `bot` varchar(191) NOT NULL,
  `changed_by` varchar(191) NOT NULL,
  `changed_at` varchar(40) NOT NULL,
  PRIMARY KEY (`bot`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
INSERT INTO `charter_change` (`bot`,`changed_by`,`changed_at`) VALUES ('wrvhtg','ad1vyx','2026-10-22T03:35:21.901029098Z');
DROP TABLE IF EXISTS `charter_change_write`;
CREATE TABLE `charter_change_write` (
  `bot` varchar(191) NOT NULL,
  `ordinal` int NOT NULL,
  `changed_by` varchar(191) NOT NULL,
  `changed_by_session` varchar(64),
  `changed_at` varchar(40) NOT NULL,
  PRIMARY KEY (`bot`,`ordinal`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
INSERT INTO `charter_change_write` (`bot`,`ordinal`,`changed_by`,`changed_by_session`,`changed_at`) VALUES ('wrvhtg',1,'ad1vyx','y2g86d','2026-10-22T03:35:21.513117862Z'), ('wrvhtg',2,'ad1vyx','y2g86d','2026-10-22T03:35:21.901029098Z');
DROP TABLE IF EXISTS `displaced_type_field`;
CREATE TABLE `displaced_type_field` (
  `type_name` varchar(191) NOT NULL,
  `key_name` varchar(191) NOT NULL,
  `ordinal` int NOT NULL,
  `holds` varchar(32) NOT NULL,
  `folds` varchar(16) NOT NULL DEFAULT 'newest',
  `required` tinyint(1) NOT NULL DEFAULT '1',
  `one_of` text,
  `replaced_on` varchar(16) NOT NULL,
  PRIMARY KEY (`type_name`,`key_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
DROP TABLE IF EXISTS `entity`;
CREATE TABLE `entity` (
  `id` varchar(191) NOT NULL,
  `kind` varchar(32) NOT NULL,
  `name` text NOT NULL,
  `source` varchar(255) NOT NULL,
  `crm` varchar(255),
  `parent` varchar(191),
  `boot` varchar(16) NOT NULL,
  `prose` longtext NOT NULL,
  `badge` varchar(16),
  `merged_into` varchar(191),
  `archived_reason` text,
  `archived_at` varchar(40),
  PRIMARY KEY (`id`),
  KEY `by_kind` (`kind`),
  KEY `by_parent` (`parent`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
